window.RTLBenchLSData.register("assets/d34fd94a9352cf6f03479497c9380f90a7b3e11ca388eaf17522ab7c51b60143.txt","{\n  \"pr_url\": \"https://github.com/lowRISC/opentitan/pull/12508\",\n  \"issue_url\": \"https://github.com/lowRISC/opentitan/issues/12274\",\n  \"repository\": \"lowRISC/opentitan\",\n  \"pr_number\": 12508,\n  \"issue_number\": 12274,\n  \"verilog_files\": [\n    \"hw/ip/clkmgr/rtl/clkmgr_trans.sv\"\n  ],\n  \"deletions\": 2,\n  \"additions\": 5,\n  \"patches\": [\n    {\n      \"filename\": \"hw/ip/clkmgr/rtl/clkmgr_trans.sv\",\n      \"patch\": \"@@ -28,13 +28,16 @@ module clkmgr_trans\\n   import prim_mubi_pkg::mubi4_test_true_strict;\\n   import prim_mubi_pkg::mubi4_test_false_loose;\\n \\n-  localparam int TransIdleCnt = int'(MuBi4True);\\n+  // Note this value is specifically chosen.\\n+  // The binary value is 1010, which is a balanced 4-bit value\\n+  // that should in theory be resistant to all 0 or all 1 attacks.\\n+  localparam int TransIdleCnt = 10;\\n   localparam int IdleCntWidth = $clog2(TransIdleCnt + 1);\\n \\n   logic [IdleCntWidth-1:0] idle_cnt;\\n   logic idle_valid;\\n   logic sw_hint_synced;\\n-  assign idle_valid = (idle_cnt == MuBi4True);\\n+  assign idle_valid = (idle_cnt == TransIdleCnt);\\n   assign clk_en_o = sw_hint_synced | ~idle_valid;\\n \\n   prim_flop_2sync #(\",\n      \"additions\": 5,\n      \"deletions\": 2,\n      \"changes\": 7\n    }\n  ],\n  \"pr_info\": {\n    \"title\": \"[clkmgr] De-couple idle count from mubi\",\n    \"body\": \"- Address issue brought up in #12274\\r\\n\\r\\nSigned-off-by: Timothy Chen <timothytim@google.com>\",\n    \"state\": \"closed\",\n    \"created_at\": \"2022-05-06T00:25:32Z\",\n    \"updated_at\": \"2022-05-06T17:23:46Z\",\n    \"merged_at\": \"2022-05-06T17:23:45Z\",\n    \"user\": \"tjaychen\"\n  },\n  \"issue_info\": {\n    \"title\": \"[clkmgr] Double check transactional clock enable logic\",\n    \"body\": \"The transactional clock enable logic below may need a second look:\\r\\nhttps://github.com/lowRISC/opentitan/blob/a7b30e63694cdf92ca70ba61f15492d6039a8e95/hw/ip/clkmgr/rtl/clkmgr_trans.sv#L31-L38\\r\\n\\r\\nSpecifically, the recent MUBI value change in #12153 leads to a lint error in this block now:\\r\\n```\\r\\nE   EQ_OP_BITLEN:   clkmgr_trans.sv:37   Bitlength mismatch between 'idle_cnt' length 3 and 'MuBi4True' length 4, instance 'clkmgr.u_clk_main_aes_trans' of module 'clkmgr_trans' (IdleCntWidth=3 ('$clog2(TransIdleCnt + 1)'),MuBi4Width=4,TransIdleCnt=6 ('int '(MuBi4True)'))                 New              \\r\\n```\\r\\nThis is because the new TRUE value does not need 4bits, but only 3bits to be represented correctly, and the code above sizes the counter accordingly.\\r\\n\",\n    \"labels\": [\n      \"Priority:P2\",\n      \"Type:Question\",\n      \"IP:clkmgr\",\n      \"Milestone:D3\"\n    ],\n    \"state\": \"closed\",\n    \"created_at\": \"2022-04-22T02:18:37Z\",\n    \"updated_at\": \"2022-05-06T17:23:52Z\"\n  },\n  \"source_info\": {\n    \"source_file\": \"12.txt\",\n    \"line_number\": 2058\n  },\n  \"base_commit\": \"7d962c8f6a9dc8703970b4432767232d0fa77cf9\",\n  \"head_commit\": \"2e3334dbf71ef3fb5479f4fddec7ace26081d1d7\",\n  \"base_ref\": \"master\",\n  \"task_id\": \"lowRISC_opentitan_12508_12274\",\n  \"lec_status\": \"useful_pass\"\n}");
